with j as (select * from jsonb_to_recordset($law7d0015$[{"code_id":"APK_RF","article_number":"279","version_date":"2002-07-24","article_text":"1. Лицо, участвующее в деле, направляет отзыв на кассационную жалобу с приложением документов, подтверждающих возражения относительно жалобы, другим лицам, участвующим в деле, и в арбитражный суд.\n\nК отзыву, направляемому в арбитражный суд, прилагается также документ, подтверждающий направление отзыва другим лицам, участвующим в деле.","article_title":"Статья 279. Отзыв на кассационную жалобу","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"66b9e12bcfaafe3e3315d18afe652ef9799346ff8537e1e221953f17bb16c0ff"},{"code_id":"APK_RF","article_number":"28","version_date":"2002-07-24","article_text":"(Наименование в редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\nАрбитражные суды рассматривают в порядке искового производства возникающие из гражданских правоотношений экономические споры и другие дела, связанные с осуществлением предпринимательской и иной экономической деятельности юридическими лицами и индивидуальными предпринимателями, а в случаях, предусмотренных настоящим Кодексом и иными федеральными законами, другими организациями и гражданами, за исключением дел, рассматриваемых Московским городским судом в соответствии с частью третьей статьи 26 Гражданского процессуального кодекса Российской Федерации. (В редакции Федерального закона от 02.07.2013 № 187-ФЗ)","article_title":"Статья 28. Компетенция арбитражных судов по экономическим спорам и иным делам, возникающим из гражданских правоотношений","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"04fb60024458f2defcfb5a4a8f478a1187c0ffdc3d88033d692d2d65ba47bbea"},{"code_id":"APK_RF","article_number":"280","version_date":"2002-07-24","article_text":"1. Арбитражный суд кассационной инстанции, установив при рассмотрении вопроса о принятии кассационной жалобы к производству, что она подана с нарушением требований, установленных статьей 277 настоящего Кодекса, выносит определение об оставлении кассационной жалобы без движения.\n\n2. В определении арбитражный суд указывает основания оставления кассационной жалобы без движения и срок, в течение которого лицо, подавшее кассационную жалобу, должно устранить обстоятельства, послужившие основанием для оставления кассационной жалобы без движения.\n\n3. Копия определения об оставлении кассационной жалобы без движения направляется лицу, подавшему кассационную жалобу, не позднее следующего дня после дня его вынесения.\n\n4. В случае, если обстоятельства, послужившие основанием для оставления кассационной жалобы без движения, будут устранены в срок, указанный в определении суда, кассационная жалоба считается поданной в день ее первоначального поступления в суд и принимается к производству арбитражного суда кассационной инстанции.\n\n5. В случае, если указанные обстоятельства не будут устранены в срок, установленный в определении, арбитражный суд возвращает кассационную жалобу и прилагаемые к ней документы лицу, подавшему жалобу, в порядке, установленном статьей 281 настоящего Кодекса.","article_title":"Статья 280. Оставление кассационной жалобы без движения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"00d1744eb1c358332e6d2a6a02e4664fa4eaf1d1405f925bd374d2d4eb5c02e2"},{"code_id":"APK_RF","article_number":"281","version_date":"2002-07-24","article_text":"1. Арбитражный суд кассационной инстанции возвращает кассационную жалобу, если при рассмотрении вопроса о принятии кассационной жалобы к производству установит, что:\n\n1) кассационная жалоба подана лицом, не имеющим права на обжалование судебного акта в порядке кассационного производства, или подана на судебный акт, который в соответствии с настоящим Кодексом не обжалуется в порядке кассационного производства;\n\n>11) кассационная жалоба не подписана или кассационная жалоба подписана  лицом, не имеющим полномочий на ее подписание; (Дополнение пунктом - Федеральный закон от 28.11.2018 № 451-ФЗ) (В редакции Федерального закона от 02.12.2019 № 406-ФЗ)\n\n2) кассационная жалоба подана по истечении срока подачи кассационной жалобы, установленного настоящим Кодексом, и не содержит ходатайство о его восстановлении или в восстановлении пропущенного срока отказано;\n\n3) до вынесения определения о принятии кассационной жалобы к производству арбитражного суда кассационной инстанции от лица, подавшего кассационную жалобу, поступило ходатайство о ее возвращении;\n\n4) не устранены обстоятельства, послужившие основанием для оставления кассационной жалобы без движения, в срок, установленный в определении суда;\n\n5) кассационная жалоба подана на судебный акт, который не был обжалован в арбитражный суд апелляционной инстанции, если иное не предусмотрено настоящим Кодексом. (Дополнение пунктом - Федеральный закон от 27.07.2010 № 228-ФЗ)\n\nАрбитражный суд кассационной инстанции также возвращает кассационную жалобу, если отклонено ходатайство о предоставлении отсрочки, рассрочки уплаты государственной пошлины, об уменьшении ее размера.\n\n2. О возвращении кассационной жалобы арбитражный суд выносит определение.\n\nКопия определения о возвращении кассационной жалобы направляется лицу, подавшему ее, вместе с кассационной жалобой и прилагаемыми к ней документами не позднее следующего дня после дня его вынесения или после истечения срока, установленного судом для устранения обстоятельств, послуживших основанием для оставления кассационной жалобы без движения.\n\n3. Определение о возвращении кассационной жалобы может быть обжаловано в арбитражный суд кассационной инстанции в порядке, установленном статьей 291 настоящего Кодекса.\n\nВ случае отмены определения кассационная жалоба считается поданной в день первоначального обращения в арбитражный суд.\n\n4. Возвращение кассационной жалобы не препятствует повторному обращению с кассационной жалобой в арбитражный суд в общем порядке после устранения обстоятельств, послуживших основанием для ее возвращения.","article_title":"Статья 281. Возвращение кассационной жалобы","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3b8c2226bc4028c5d51fc154c0b13bb3bd960ee02b1a2d4c747bd12b0fe41d0d"},{"code_id":"APK_RF","article_number":"282","version_date":"2002-07-24","article_text":"1. Арбитражный суд кассационной инстанции прекращает производство по кассационной жалобе, если после принятия кассационной жалобы к производству суда от лица, ее подавшего, поступило ходатайство об отказе от кассационной жалобы и отказ принят судом в соответствии со статьей 49 настоящего Кодекса.\n\n2. О прекращении производства по кассационной жалобе арбитражный суд выносит определение.\n\nВ определении могут быть разрешены вопросы о распределении между сторонами судебных расходов, о возврате государственной пошлины из федерального бюджета.\n\nКопии определения о прекращении производства по кассационной жалобе направляются лицам, участвующим в деле.\n\n3. В случае прекращения производства по кассационной жалобе повторное обращение того же лица по тем же основаниям в арбитражный суд с кассационной жалобой не допускается.\n\n4. Определение арбитражного суда о прекращении производства по кассационной жалобе может быть обжаловано в арбитражный суд кассационной инстанции в порядке, установленном в статье 291 настоящего Кодекса.","article_title":"Статья 282. Прекращение производства по кассационной жалобе","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"31a310e6a5b521443a3f06e49c39398330916be3f1b1848ae8581e460a57c1d8"},{"code_id":"APK_RF","article_number":"283","version_date":"2002-07-24","article_text":"1. Арбитражный суд кассационной инстанции вправе по ходатайству лиц, участвующих в деле, приостановить исполнение судебных актов, принятых арбитражным судом первой и апелляционной инстанций, при условии, если заявитель обосновал невозможность или затруднительность поворота исполнения либо предоставил обеспечение, предусмотренное в части 2 настоящей статьи.\n\nХодатайство о приостановлении исполнения судебных актов, подаваемое в электронном виде, должно быть подписано усиленной квалифицированной электронной подписью. (Дополнение абзацем - Федеральный закон от 23.06.2016 № 220-ФЗ) (В редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\n2. Исполнение решения, постановления арбитражного суда приостанавливается арбитражным судом кассационной инстанции при предоставлении лицом, ходатайствующим о таком приостановлении, обеспечения возмещения другой стороне по делу возможных убытков (встречного обеспечения) путем внесения на депозитный счет арбитражного суда кассационной инстанции денежных средств в размере оспариваемой суммы либо предоставления банковской гарантии, поручительства или иного финансового обеспечения на ту же сумму.\n\n3. О приостановлении исполнения судебного акта или об отказе в приостановлении исполнения арбитражный суд кассационной инстанции выносит определение в трехдневный срок со дня поступления ходатайства в суд. Определение может быть обжаловано в арбитражный суд кассационной инстанции. Содержание этого определения может быть изложено в определении о принятии кассационной жалобы к производству суда.\n\nКопия определения направляется лицам, участвующим в деле.\n\n4. Исполнение судебного акта приостанавливается на срок до принятия арбитражным судом кассационной инстанции постановления по результатам рассмотрения кассационной жалобы, если судом не установлен иной срок приостановления.","article_title":"Статья 283. Приостановление исполнения судебных актов арбитражным судом кассационной инстанции","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1b4aba32726428bce9e796c5a75d0857f713f8ae0e639ccb324361b0b2830265"},{"code_id":"APK_RF","article_number":"285","version_date":"2002-07-24","article_text":"(Статья в редакции Федерального закона от 30.04.2010 № 69-ФЗ)","article_title":"Статья 285. Срок рассмотрения кассационной жалобы","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3719fd3804ca9e264fffb5107da372c727e94e80dbaef9c4f409dfde93141e50"},{"code_id":"APK_RF","article_number":"286","version_date":"2002-07-24","article_text":"1. Арбитражный суд кассационной инстанции проверяет законность решений, постановлений, принятых арбитражным судом первой и апелляционной инстанций, устанавливая правильность применения норм материального права и норм процессуального права при рассмотрении дела и принятии обжалуемого судебного акта и исходя из доводов, содержащихся в кассационной жалобе и возражениях относительно жалобы, если иное не предусмотрено настоящим Кодексом.\n\n2. Независимо от доводов, содержащихся в кассационной жалобе, арбитражный суд кассационной инстанции проверяет, не нарушены ли арбитражным судом первой и апелляционной инстанций нормы процессуального права, являющиеся в соответствии с частью 4 статьи 288 настоящего Кодекса основанием для отмены решения арбитражного суда первой инстанции, постановления арбитражного суда апелляционной инстанции.\n\n3. При рассмотрении дела арбитражный суд кассационной инстанции проверяет, соответствуют ли выводы арбитражного суда первой и апелляционной инстанций о применении нормы права установленным ими по делу обстоятельствам и имеющимся в деле доказательствам.","article_title":"Статья 286. Пределы рассмотрения дела в арбитражном суде кассационной инстанции","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"65258f1783ba605e5760d81232499d122ba32a7b121ecd71cb591ff9d62436b4"},{"code_id":"APK_RF","article_number":"287","version_date":"2002-07-24","article_text":"1. По результатам рассмотрения кассационной жалобы арбитражный суд кассационной инстанции вправе:\n\n1) оставить решение арбитражного суда первой инстанции и (или) постановление суда апелляционной инстанции без изменения, а кассационную жалобу без удовлетворения;\n\n2) отменить или изменить решение суда первой инстанции и (или) постановление суда апелляционной инстанции полностью или в части и, не передавая дело на новое рассмотрение, принять новый судебный акт, если фактические обстоятельства, имеющие значение для дела, установлены арбитражным судом первой и апелляционной инстанций на основании полного и всестороннего исследования имеющихся в деле доказательств, но этим судом неправильно применена норма права либо законность решения, постановления арбитражного суда первой и апелляционной инстанций повторно проверяется арбитражным судом кассационной инстанции при отсутствии оснований, предусмотренных пунктом 3 части 1 настоящей статьи;\n\n3) отменить или изменить решение суда первой инстанции и (или) постановление суда апелляционной инстанции полностью или в части и направить дело на новое рассмотрение в соответствующий арбитражный суд, решение, постановление которого отменено или изменено, если этим судом нарушены нормы процессуального права, являющиеся в соответствии с частью 4 статьи 288 настоящего Кодекса основанием для отмены решения, постановления, или если выводы, содержащиеся в обжалуемых решении, постановлении, не соответствуют установленным по делу фактическим обстоятельствам или имеющимся в деле доказательствам. При направлении дела на новое рассмотрение суд может указать на необходимость рассмотрения дела коллегиальным составом судей и (или) в ином судебном составе;\n\n4) отменить или изменить решение суда первой инстанции и (или) постановление суда апелляционной инстанции полностью или в части и передать дело на рассмотрение другого арбитражного суда первой или апелляционной инстанции в пределах одного и того же судебного округа, если указанные судебные акты повторно проверяются арбитражным судом кассационной инстанции и содержащиеся в них выводы не соответствуют установленным по делу фактическим обстоятельствам или имеющимся в деле доказательствам;\n\n5) оставить в силе одно из ранее принятых по делу решений или постановлений;\n\n6) отменить решение суда первой инстанции и (или) постановление суда апелляционной инстанции полностью или в части и прекратить производство по делу либо оставить исковое заявление без рассмотрения полностью или в части.\n\n2. Арбитражный суд, рассматривающий дело в кассационной инстанции, не вправе устанавливать или считать доказанными обстоятельства, которые не были установлены в решении или постановлении либо были отвергнуты судом первой или апелляционной инстанции, предрешать вопросы о достоверности или недостоверности того или иного доказательства, преимуществе одних доказательств перед другими, о том, какая норма материального права должна быть применена и какое решение, постановление должно быть принято при новом рассмотрении дела.","article_title":"Статья 287. Полномочия арбитражного суда кассационной инстанции","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1efce6471deaa3cba4b35842192ffeb2facb8c4a02f1ffb6005e200b35e8fb0d"},{"code_id":"APK_RF","article_number":"288","version_date":"2002-07-24","article_text":"(Наименование в редакции Федерального закона от 02.03.2016 № 47-ФЗ)\n\n1. Основаниями для изменения или отмены решения, постановления арбитражного суда первой и апелляционной инстанций являются несоответствие выводов суда, содержащихся в решении, постановлении, фактическим обстоятельствам дела, установленным арбитражным судом первой и апелляционной инстанций, и имеющимся в деле доказательствам, нарушение либо неправильное применение норм материального права или норм процессуального права.\n\n2. Неправильным применением норм материального права являются:\n\n1) неприменение закона, подлежащего применению;\n\n2) применение закона, не подлежащего применению;\n\n3) неправильное истолкование закона.\n\n3. Нарушение или неправильное применение норм процессуального права является основанием для изменения или отмены решения, постановления арбитражного суда, если это нарушение привело или могло привести к принятию неправильного решения, постановления.\n\n1) рассмотрение дела арбитражным судом в незаконном составе;\n\n2) рассмотрение дела в отсутствие кого-либо из лиц, участвующих в деле и не извещенных надлежащим образом о времени и месте судебного заседания;\n\n3) нарушение правил о языке при рассмотрении дела;\n\n4) принятие судом решения, постановления о правах и об обязанностях лиц, не привлеченных к участию в деле;\n\n5) неподписание решения, постановления судьей или одним из судей либо подписание решения, постановления не теми судьями, которые указаны в решении, постановлении;\n\n6) отсутствие в деле протокола судебного заседания или подписание его не теми лицами, которые указаны в статье 155 настоящего Кодекса, в случае отсутствия аудиозаписи судебного заседания; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n7) нарушение правила о тайне совещания судей при принятии решения, постановления.","article_title":"Статья 288. Основания для отмены судебного приказа, изменения или отмены решения, постановления арбитражного суда первой и апелляционной инстанций","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"738dd506bcc71319ae7dee59ad7c282bd056fc090a1b206757c493e77c6ea297"},{"code_id":"APK_RF","article_number":"288.1","version_date":"2002-07-24","article_text":"1. Вступившие в законную силу судебные приказы арбитражных судов первой инстанции могут быть обжалованы в порядке кассационного производства по правилам, предусмотренным настоящей главой, с учетом особенностей, установленных настоящей статьей.\n\n1) оставить судебный приказ без изменения, а кассационную жалобу без удовлетворения;\n\n2) (Пункт утратил силу - Федеральный закон от 23.06.2016 № 220-ФЗ)\n\n3) отменить судебный приказ и направить дело на новое рассмотрение, если имеются основания, указанные в части 4 настоящей статьи;\n\n4) (Пункт утратил силу - Федеральный закон от 23.06.2016 № 220-ФЗ)\n\n5) отменить судебный приказ, указав при этом в постановлении на право взыскателя предъявить требование в порядке искового производства или производства по делам, возникающим из административных и иных публичных правоотношений. (Дополнение пунктом - Федеральный закон от 19.12.2016 № 435-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 02.03.2016 № 47-ФЗ)","article_title":"Статья 288.1. Особенности кассационного производства, связанные с пересмотром вступившего в законную силу судебного приказа","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ed87378b1555923602e4d37c9dfae465c37c5302394e75b0651718be3a1880e7"},{"code_id":"APK_RF","article_number":"288.2","version_date":"2002-07-24","article_text":"1. Вступившие в законную силу решения арбитражного суда первой инстанции и постановления арбитражного суда апелляционной инстанции, принятые по делам, рассмотренным в порядке упрощенного производства, могут быть обжалованы в порядке кассационного производства по правилам, предусмотренным настоящей главой, с учетом особенностей, установленных настоящей статьей.\n\n(Дополнение статьей - Федеральный закон от 02.03.2016 № 45-ФЗ)","article_title":"Статья 288.2. Кассационные жалобы на решения арбитражного суда первой инстанции и постановления арбитражного суда апелляционной инстанции по делам, рассмотренным в порядке упрощенного производства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cd606b71eb09e1a48b86f88b8ea0f9bf64501e69bb0bc079d4a934a5dfccf9a6"},{"code_id":"APK_RF","article_number":"289","version_date":"2002-07-24","article_text":"1. По результатам рассмотрения кассационной жалобы арбитражный суд кассационной инстанции принимает судебный акт, именуемый постановлением, которое подписывается судьями, рассматривавшими дело.\n\n2. В постановлении арбитражного суда кассационной инстанции должны быть указаны:\n\n1) наименование арбитражного суда кассационной инстанции, состав суда, принявшего постановление;\n\n2) номер дела, дата и место принятия постановления;\n\n3) наименование лица, подавшего кассационную жалобу, его процессуальное положение;\n\n4) наименования лиц, участвующих в деле;\n\n5) предмет спора;\n\n6) фамилии лиц, присутствовавших в судебном заседании, с указанием их полномочий;\n\n7) наименования арбитражных судов, рассмотревших дело в первой и апелляционной инстанциях; дата принятия обжалуемых судебного приказа, решения, постановления; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n8) краткое изложение содержания принятых по делу решения, судебного приказа, постановления;\n\n9) основания, по которым в кассационной жалобе заявлены требования о проверке законности решения, судебного приказа, постановления;\n\n10) доводы, изложенные в отзыве на кассационную\n\n11) объяснения лиц, участвующих в деле и присутствовавших в судебном заседании;\n\n12) законы и иные нормативные правовые акты, которыми руководствовался суд кассационной инстанции при принятии постановления; мотивы принятого постановления; мотивы, по которым суд не применил законы и иные нормативные правовые акты, на которые ссылались лица, участвующие в деле;\n\n13) мотивы, по которым суд кассационной инстанции не согласился с выводами арбитражных судов первой и апелляционной инстанций, если их решение, судебный приказ, постановление были отменены полностью или в части;\n\n14) выводы по результатам рассмотрения кассационной жалобы;\n\n15) действия, которые должны быть выполнены лицами, участвующими в деле, и арбитражным судом первой или апелляционной инстанции, если дело передается на новое рассмотрение.\n\n(Часть в редакции Федерального закона от 02.03.2016 № 47-ФЗ)\n\n3. В постановлении арбитражного суда кассационной инстанции указывается на распределение между сторонами судебных расходов, понесенных в связи с подачей кассационной жалобы.\n\nПри отмене судебного акта с передачей дела на новое рассмотрение вопрос о распределении судебных расходов разрешается арбитражным судом, вновь рассматривающим дело.\n\n4. Копии постановления арбитражного суда кассационной инстанции направляются лицам, участвующим в деле, в пятидневный срок со дня принятия постановления.\n\n5. Постановление арбитражного суда кассационной инстанции вступает в законную силу со дня его принятия.","article_title":"Статья 289. Постановление арбитражного суда кассационной инстанции","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fbdd7006b1a360e2972f84f5bc5c558816e8662321c79a809a8e244f1a0a32a9"},{"code_id":"APK_RF","article_number":"29","version_date":"2002-07-24","article_text":"(Наименование в редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n1) (Пункт утратил силу - Федеральный закон от 30.12.2012 № 317-ФЗ)\n\n11) об оспаривании нормативных правовых актов федеральных органов исполнительной власти, если рассмотрение таких дел в соответствии с настоящим Кодексом отнесено к компетенции Суда по интеллектуальным правам; (Дополнение пунктом - Федеральный закон от 30.12.2012 № 317-ФЗ) (В редакции Федерального закона от 28.06.2014 № 186-ФЗ)\n\n12) об оспаривании актов федеральных органов исполнительной власти, содержащих разъяснения законодательства и обладающих нормативными свойствами, если рассмотрение таких дел в соответствии с настоящим Кодексом отнесено к компетенции Суда по интеллектуальным правам; (Дополнение пунктом - Федеральный закон от 15.02.2016 № 18-ФЗ)\n\n2) об оспаривании затрагивающих права и законные интересы заявителя в сфере предпринимательской и иной экономической деятельности ненормативных правовых актов, решений и действий (бездействия) государственных органов, органов местного самоуправления, иных органов, организаций, наделенных федеральным законом отдельными государственными или иными публичными полномочиями, должностных лиц; (В редакции Федерального закона от 27.07.2010 № 228-ФЗ)\n\n3) об административных правонарушениях, если федеральным законом их рассмотрение отнесено к компетенции арбитражного суда;\n\n4) о взыскании с организаций и граждан, осуществляющих предпринимательскую и иную экономическую деятельность, обязательных платежей, санкций, если федеральным законом не предусмотрен иной порядок их взыскания;\n\n5) другие дела, возникающие из административных и иных публичных правоотношений, если федеральным законом их рассмотрение отнесено к компетенции арбитражного суда.","article_title":"Статья 29. Компетенция арбитражных судов по экономическим спорам и другим делам, возникающим из административных и иных публичных правоотношений","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"70cb7c06e52a922521b9597c7fc288d599a45d39e71d1916078a30d54e7a6fb2"},{"code_id":"APK_RF","article_number":"290","version_date":"2002-07-24","article_text":"1. Кассационные жалобы на определения арбитражного суда первой и апелляционной инстанций, поданные по правилам, установленным настоящим Кодексом, рассматриваются арбитражным судом кассационной инстанции в порядке, предусмотренном настоящей главой для рассмотрения кассационных жалоб на решения и постановления соответствующего арбитражного суда.\n\n2. Кассационные жалобы на определения арбитражного суда апелляционной инстанции о возвращении апелляционной жалобы и на другие препятствующие дальнейшему движению дела определения рассматриваются арбитражным судом кассационной инстанции в срок, не превышающий пятнадцати дней со дня поступления такой жалобы в арбитражный суд кассационной инстанции.\n\n(Статья в редакции Федерального закона от 19.07.2009 № 205-ФЗ)","article_title":"Статья 290. Кассационные жалобы на определения арбитражного суда первой и апелляционной инстанций","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bfc0ed08d7317d73ff510ab50ea25116c3a283b3327503045f5c5b7ca58d45ff"},{"code_id":"APK_RF","article_number":"291","version_date":"2002-07-24","article_text":"1. Жалобы на определение арбитражного суда кассационной инстанции о возвращении кассационной жалобы, поданные в арбитражный суд кассационной инстанции, вынесший такое определение, рассматриваются коллегиальным составом судей этого же суда в десятидневный срок со дня поступления жалобы в суд без извещения сторон.\n\n2. Жалобы на другие определения арбитражного суда кассационной инстанции, обжалование которых предусмотрено настоящим Кодексом, рассматриваются тем же арбитражным судом кассационной инстанции в ином судебном составе в порядке, предусмотренном настоящей главой.\n\n3. По результатам рассмотрения жалобы на определение арбитражного суда кассационной инстанции выносится определение.","article_title":"Статья 291. Жалобы на определение арбитражного суда кассационной инстанции","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"88f9df6755102e12ec004449eca90b70cafbffed69ff53d5b25b5b7a1fdc03f8"},{"code_id":"APK_RF","article_number":"291.1","version_date":"2002-07-24","article_text":"1. Судебные акты могут быть полностью или в части обжалованы в Судебную коллегию Верховного Суда Российской Федерации в порядке кассационного производства лицами, участвующими в деле, а также иными лицами в случаях, предусмотренных настоящим Кодексом, если в оспариваемых судебных актах содержатся существенные нарушения норм материального права и (или) норм процессуального права, повлиявшие на исход судебного разбирательства и приведшие к нарушению их прав и законных интересов в сфере предпринимательской и иной экономической деятельности.\n\n2. Кассационные жалобы в Судебную коллегию Верховного Суда Российской Федерации подаются на вступившие в законную силу:\n\n1) решения и определения арбитражных судов республик, краев, областей, городов федерального значения, автономной области, автономных округов; постановления и определения арбитражных апелляционных судов; решения и определения арбитражных судов округов, принятые ими в первой инстанции; решения и определения Суда по интеллектуальным правам, принятые им в первой инстанции; определения арбитражных судов округов и Суда по интеллектуальным правам, вынесенные ими в процессе кассационного производства, если судебные акты, в отношении которых настоящим Кодексом предусмотрена возможность обжалования в порядке кассационного производства в арбитражный суд округа, обжаловались в указанном порядке; постановления и определения арбитражных судов округов и Суда по интеллектуальным правам, принятые по результатам рассмотрения кассационной жалобы (жалобы);\n\n2) судебные акты арбитражных судов, в отношении которых настоящим Кодексом возможность обжалования в порядке кассационного производства в арбитражный суд округа не предусмотрена, если они были предметом рассмотрения в арбитражном суде апелляционной инстанции, и постановление арбитражного суда апелляционной инстанции, принятое по данному делу.\n\n3. Постановления арбитражных судов округов, которыми не были отменены судебные приказы, отменены или изменены судебные акты, принятые в порядке упрощенного производства, не подлежат обжалованию в Судебную коллегию Верховного Суда Российской Федерации.\n\n4. Лицо, полагающее, что нарушено его право на судопроизводство в разумный срок, вправе подать в Судебную коллегию Верховного Суда Российской Федерации кассационную жалобу, в которой также могут быть изложены требования о присуждении ему компенсации.\n\n5. Генеральный прокурор Российской Федерации и заместители Генерального прокурора Российской Федерации вправе обратиться в Судебную коллегию Верховного Суда Российской Федерации с представлением о пересмотре в порядке кассационного производства вступивших в законную силу судебных актов, принятых по делам, участие прокурора в которых предусмотрено настоящим Кодексом.\n\n6. Кассационные жалоба, представление подаются непосредственно в Верховный Суд Российской Федерации.\n\n(Дополнение статьей - Федеральный закон от 28.06.2014 № 186-ФЗ) (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)","article_title":"Статья 291.1. Порядок подачи кассационных жалобы, представления в Судебную коллегию Верховного Суда Российской Федерации","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c4cfe4a2b5d48ef70cd2b070e8cc04799122c57cd5cef3e58597ba6a330db29b"}]$law7d0015$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at)
